using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace MSFSBlindAssist.Aircraft.A330;

/// <summary>
/// The iniBuilds A330 (MSFS 2024) cockpit control map, GENERATED by tools/a330-gen. The aircraft is
/// a streamed, encrypted package, so the map is not read from its behaviour files (as the A300's is)
/// but MEASURED: every control is one of the aircraft's own FS2024 input events (<c>B:AIRLINER_*</c>,
/// listed by SimConnect's EnumerateInputEvents), and the generator's probe set each one and recorded
/// which <c>INI_*</c> L:var the aircraft moved in answer. Regenerate it — never hand-edit the JSON.
///
/// A position carries TWO numbers because they differ on most controls: <see cref="Position.Input"/>
/// is the value written to the input event, <see cref="Position.Value"/> is what the read-back L:var
/// shows for it (pack 1: input 0 = on, and <c>INI_PACK1_BUTTON</c> reads 1 when on).
/// </summary>
internal sealed class A330ControlMap
{
    public const string ResourceName = "MSFSBlindAssist.Resources.a330_control_map.json";

    public sealed class Section
    {
        [JsonPropertyName("name")] public string Name { get; set; } = "";
        [JsonPropertyName("panels")] public List<string> Panels { get; set; } = new();
    }

    public sealed class Position
    {
        /// <summary>The read-back L:var's value in this position.</summary>
        [JsonPropertyName("value")] public double Value { get; set; }
        /// <summary>The value written to the input event to select this position.</summary>
        [JsonPropertyName("input")] public double Input { get; set; }
        [JsonPropertyName("label")] public string Label { get; set; } = "";
    }

    public sealed class Lamp
    {
        [JsonPropertyName("read")] public string Read { get; set; } = "";
        [JsonPropertyName("legend")] public string Legend { get; set; } = "";
    }

    public sealed class Control
    {
        [JsonPropertyName("key")] public string Key { get; set; } = "";
        [JsonPropertyName("section")] public string Section { get; set; } = "";
        [JsonPropertyName("panel")] public string Panel { get; set; } = "";
        [JsonPropertyName("label")] public string Label { get; set; } = "";
        /// <summary>select | button | encoder | continuous | status</summary>
        [JsonPropertyName("kind")] public string Kind { get; set; } = "";
        /// <summary>The aircraft's input event (no <c>B:</c> prefix).</summary>
        [JsonPropertyName("event")] public string? Event { get; set; }
        /// <summary>How a pick reaches the aircraft: <c>set</c> = SetInputEvent with the position's
        /// input value (selectors, latching switches); <c>push</c> = the event's own <c>_Push</c> then
        /// <c>_Release</c> actions over the calculator path (momentary keys — a raw value does nothing
        /// on them, measured); <c>rpn</c> = <see cref="Rpn"/> with <c>{value}</c> substituted.</summary>
        [JsonPropertyName("mode")] public string Mode { get; set; } = "set";
        [JsonPropertyName("rpn")] public string? Rpn { get; set; }
        /// <summary>The read-back variable: an <c>INI_*</c> L:var name, or <c>A:NAME, unit</c>.</summary>
        [JsonPropertyName("read")] public string? Read { get; set; }
        [JsonPropertyName("positions")] public List<Position>? Positions { get; set; }
        /// <summary>A button: the input value of the press (released back to <see cref="Release"/>).</summary>
        [JsonPropertyName("press")] public double? Press { get; set; }
        [JsonPropertyName("release")] public double? Release { get; set; }
        [JsonPropertyName("holdMs")] public int? HoldMs { get; set; }
        /// <summary>A continuous control's range (input values; the read-back shows the same scale).</summary>
        [JsonPropertyName("min")] public double? Min { get; set; }
        [JsonPropertyName("max")] public double? Max { get; set; }
        [JsonPropertyName("step")] public double? Step { get; set; }
        [JsonPropertyName("lamps")] public List<Lamp>? Lamps { get; set; }
        [JsonPropertyName("notes")] public string? Notes { get; set; }
    }

    [JsonPropertyName("version")] public int Version { get; set; }
    [JsonPropertyName("sections")] public List<Section> Sections { get; set; } = new();
    [JsonPropertyName("controls")] public List<Control> Controls { get; set; } = new();

    private static readonly Lazy<A330ControlMap> _embedded = new(() => Load(ResourceName));
    public static A330ControlMap Embedded => _embedded.Value;

    /// <summary>The iniBuilds A321LR (MSFS 2024) map — same schema, generated by tools/a321-gen.</summary>
    internal const string A321ResourceName = "MSFSBlindAssist.Resources.a321_control_map.json";
    private static readonly Lazy<A330ControlMap> _a321 = new(() => Load(A321ResourceName));
    public static A330ControlMap A321 => _a321.Value;

    internal static A330ControlMap Load(string resource)
    {
        using var s = Assembly.GetExecutingAssembly().GetManifestResourceStream(resource);
        if (s == null) return new A330ControlMap();
        return JsonSerializer.Deserialize<A330ControlMap>(s) ?? new A330ControlMap();
    }

    internal static A330ControlMap Parse(string json) =>
        JsonSerializer.Deserialize<A330ControlMap>(json) ?? new A330ControlMap();

    public enum ReadKind { LVar, SimVar, InputEvent }

    /// <summary>"INI_x" / "L:INI_x" → L:var; "A:NAME, unit" → SimVar; "B:EVENT" → the input event's own value.</summary>
    public static (ReadKind kind, string name, string units) ParseReadKind(string read)
    {
        var r = read.Trim();
        if (r.StartsWith("B:", StringComparison.OrdinalIgnoreCase)) return (ReadKind.InputEvent, r[2..].Trim(), "number");
        var (isL, n, u) = ParseRead(r);
        return (isL ? ReadKind.LVar : ReadKind.SimVar, n, u);
    }

    /// <summary>"INI_x" / "L:INI_x" → (LVar, "INI_x", "number"); "A:NAME, unit" → (SimVar, "NAME", "unit").</summary>
    public static (bool isLVar, string name, string units) ParseRead(string read)
    {
        var r = read.Trim();
        if (r.StartsWith("A:", StringComparison.OrdinalIgnoreCase))
        {
            var n = r[2..];
            int comma = n.IndexOf(',');
            return comma >= 0 ? (false, n[..comma].Trim(), n[(comma + 1)..].Trim()) : (false, n.Trim(), "number");
        }
        if (r.StartsWith("L:", StringComparison.OrdinalIgnoreCase)) r = r[2..];
        return (true, r.Trim(), "number");
    }

    /// <summary>The input value that selects the position whose read-back is <paramref name="readValue"/>
    /// (nearest match), or null when the control has no positions.</summary>
    public static double? InputFor(Control c, double readValue)
    {
        if (c.Positions is not { Count: > 0 } ps) return null;
        return ps.OrderBy(p => Math.Abs(p.Value - readValue)).First().Input;
    }
}
